+func dedupe(lines []string) []entry {
+	index := make(map[string]int, len(lines))
+	var out []entry
+	for _, l := range lines {
+		if i, ok := index[l]; ok {
+			out[i].n++
+			continue
+		}
+		index[l] = len(out)
+		out = append(out, entry{line: l, n: 1})
+	}
+	return out
+}
