+func render(w io.Writer, entries []entry, count bool) {
+	for _, e := range entries {
+		if count {
+			fmt.Fprintf(w, "%7d %s\n", e.n, e.line)
+		} else {
+			fmt.Fprintln(w, e.line)
+		}
+	}
